namespace Jellyfin.Plugin.MediaIntegrity.Models;

/// <summary>
/// Represents the persistent repair queue generated by an integrity scan.
/// </summary>
public sealed class RepairQueue
{
    public int Version { get; set; } = 1;

    public DateTimeOffset GeneratedAt { get; set; } =
        DateTimeOffset.UtcNow;

    public RepairQueueSummary Summary { get; set; } =
        new();

    public List<RepairQueueItem> Files { get; set; } =
        [];
}
